def seed_calendar(apps, schema_editor):
    CalendarTask = apps.get_model('api', 'CalendarTask')
    created = 0
    for crop_type, month, task_type, title, detail in TEMPLATE:
        _, is_new = CalendarTask.objects.get_or_create(
            crop_type=crop_type, month=month, title=title,
            defaults={'task_type': task_type, 'detail': detail, 'source': '通用模板', 'is_active': True},
        )
        created += 1 if is_new else 0
    print(f'    种植日历通用模板：新增 {created} 条，共 {len(TEMPLATE)} 条')


